-- GENERATED by `python -m wtpw.pipeline render` from sql/. Do not edit by hand.

CREATE OR REFRESH MATERIALIZED VIEW silver_segment_actuals AS
-- Annual segment sales and operating profit from each year's ORIGINAL 10-K (the earliest 10-K
-- carrying segment facts for that year), taken as one set so renamed or resegmented members
-- (Space Systems -> Space; RTX, NOC, LHX reorganizations) are never mixed across filings.
-- Within that filing: a fact on the OperatingSegmentsMember context wins over a segment-only
-- context (RTX tags both: external vs including intersegment), and Revenues wins over
-- RevenueFromContractWithCustomer... when both are tagged.
WITH candidates AS (
  SELECT ticker, fiscal_year, segment_name, accession, filing_date, value, consolidation_item, concept,
         CASE WHEN concept = 'us-gaap:OperatingIncomeLoss' THEN 'SegmentOP' ELSE 'Sales' END AS account
  FROM bronze_facts
  WHERE form = '10-K'
    AND duration_days BETWEEN 350 AND 380
    AND is_current_period
    AND concept IN ('us-gaap:Revenues', 'us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax',
                    'us-gaap:OperatingIncomeLoss')
    AND segment IS NOT NULL
    -- Reconciling items some filers (UTC-era RTX) tag on the segment axis; not segments.
    AND segment_name NOT IN ('TotalSegments', 'EliminationsAndOther', 'GeneralCorporateExpenses',
                             'AcquisitionAccountingAdjustments', 'FASCASOperatingAdjustment')
    AND other_dims = 0
    AND (consolidation_item IS NULL OR consolidation_item = 'us-gaap:OperatingSegmentsMember')
), original AS (
  SELECT ticker, fiscal_year, accession
  FROM (
    SELECT ticker, fiscal_year, accession,
           ROW_NUMBER() OVER (PARTITION BY ticker, fiscal_year ORDER BY MIN(filing_date), accession) AS rn
    FROM candidates GROUP BY ticker, fiscal_year, accession
  ) f
  WHERE rn = 1
), ranked AS (
  SELECT c.*,
         ROW_NUMBER() OVER (
           PARTITION BY c.ticker, c.fiscal_year, c.segment_name, c.account
           ORDER BY CASE WHEN c.consolidation_item = 'us-gaap:OperatingSegmentsMember' THEN 0 ELSE 1 END,
                    CASE WHEN c.concept = 'us-gaap:Revenues' THEN 0 ELSE 1 END
         ) AS rn
  FROM candidates c
  JOIN original o ON o.ticker = c.ticker AND o.fiscal_year = c.fiscal_year AND o.accession = c.accession
)
SELECT ticker, fiscal_year, segment_name AS entity, account,
       value / 1000000.0 AS value_usd_m, accession, filing_date
FROM ranked
WHERE rn = 1;

CREATE OR REFRESH MATERIALIZED VIEW silver_consolidated_actuals AS
-- Company-level annual sales and operating profit (no dimensions), as first reported.
SELECT ticker, fiscal_year, account, value / 1000000.0 AS value_usd_m, accession, filing_date
FROM (
  SELECT ticker, fiscal_year, accession, filing_date, value,
         CASE WHEN concept = 'us-gaap:OperatingIncomeLoss' THEN 'ConsolidatedOP' ELSE 'Sales' END AS account,
         ROW_NUMBER() OVER (
           PARTITION BY ticker, fiscal_year,
                        CASE WHEN concept = 'us-gaap:OperatingIncomeLoss' THEN 'ConsolidatedOP' ELSE 'Sales' END
           ORDER BY filing_date, CASE WHEN concept = 'us-gaap:Revenues' THEN 0 ELSE 1 END, accession
         ) AS rn
  FROM bronze_facts
  WHERE form = '10-K'
    AND duration_days BETWEEN 350 AND 380
    AND is_current_period
    AND concept IN ('us-gaap:Revenues', 'us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax',
                    'us-gaap:OperatingIncomeLoss')
    AND n_dims = 0
) ranked
WHERE rn = 1;

CREATE OR REFRESH MATERIALIZED VIEW silver_guidance AS
-- Guidance vintages (Plan = first annual outlook, Fcst_Q1..Q3 = later updates), typed.
-- Every row passed quote_check against the cached filing before upload.
SELECT ticker, CAST(fiscal_year AS INT) AS fiscal_year, vintage AS scenario,
       CAST(release_date AS DATE) AS release_date, accession, document, entity, metric AS account, basis,
       CAST(low AS DOUBLE) AS low, CAST(high AS DOUBLE) AS high,
       (CAST(low AS DOUBLE) + CAST(high AS DOUBLE)) / 2.0 AS mid, unit
FROM bronze_guidance;

CREATE OR REFRESH MATERIALIZED VIEW silver_charges AS
-- Disclosed program charges (reach-forward losses), pre-tax, USD millions, positive = loss.
SELECT ticker, CAST(fiscal_year AS INT) AS fiscal_year, quarter, segment, program,
       CAST(amount AS DOUBLE) AS amount_usd_m, accession, document
FROM bronze_charges;

CREATE OR REFRESH MATERIALIZED VIEW silver_eac AS
-- Disclosed EAC (profit booking rate) adjustment series, USD millions, sign as disclosed.
SELECT ticker, CAST(fiscal_year AS INT) AS fiscal_year, entity, metric AS account,
       CAST(value AS DOUBLE) AS value_usd_m, accession, document
FROM bronze_eac;

CREATE OR REFRESH MATERIALIZED VIEW gold_cube AS
-- OneStream-style cube in long form: Entity x Scenario x Account x Time, UD1 = program.
-- Actual Sales = consolidated; Actual SegmentOP = sum of reported segments (LMT's
-- "business segment operating profit"). Charges enter as negative ProgramCharge.
SELECT ticker, fiscal_year, entity, scenario, account, CAST(NULL AS STRING) AS ud1_program,
       mid AS value_usd_m, low, high, 'guidance' AS source, accession
FROM silver_guidance
UNION ALL
SELECT ticker, fiscal_year, ticker, 'Actual', account, CAST(NULL AS STRING),
       value_usd_m, CAST(NULL AS DOUBLE), CAST(NULL AS DOUBLE), 'xbrl_consolidated', accession
FROM silver_consolidated_actuals WHERE account = 'Sales'
UNION ALL
SELECT ticker, fiscal_year, ticker, 'Actual', 'SegmentOP', CAST(NULL AS STRING),
       SUM(value_usd_m), CAST(NULL AS DOUBLE), CAST(NULL AS DOUBLE), 'xbrl_segments', MIN(accession)
FROM silver_segment_actuals WHERE account = 'SegmentOP'
GROUP BY ticker, fiscal_year
UNION ALL
SELECT ticker, fiscal_year, ticker || '.' || entity, 'Actual', account, CAST(NULL AS STRING),
       value_usd_m, CAST(NULL AS DOUBLE), CAST(NULL AS DOUBLE), 'xbrl_segments', accession
FROM silver_segment_actuals
UNION ALL
SELECT ticker, fiscal_year, ticker || '.' || segment, 'Actual', 'ProgramCharge', program,
       -amount_usd_m, CAST(NULL AS DOUBLE), CAST(NULL AS DOUBLE), 'disclosure', accession
FROM silver_charges
UNION ALL
SELECT ticker, fiscal_year, entity, 'Actual', account, CAST(NULL AS STRING),
       value_usd_m, CAST(NULL AS DOUBLE), CAST(NULL AS DOUBLE), 'disclosure', accession
FROM silver_eac;

CREATE OR REFRESH MATERIALIZED VIEW gold_bridge AS
-- Plan-to-actual bridge for segment operating profit, one row per company-year with a Plan:
--   plan midpoint
--   + volume: (actual sales - plan sales midpoint) x plan margin (plan OP mid / plan sales mid)
--   - named program charges disclosed for the year
--   + other: everything not explained above (rates, mix, other EAC movement), never hidden
--   = actual.  The four steps sum to actual by construction; the test checks it independently.
WITH plan AS (
  SELECT ticker, fiscal_year,
         MAX(CASE WHEN account = 'Sales' THEN mid END) AS plan_sales,
         MAX(CASE WHEN account = 'SegmentOP' THEN mid END) AS plan_op
  FROM silver_guidance WHERE scenario = 'Plan' GROUP BY ticker, fiscal_year
), actual AS (
  SELECT ticker, fiscal_year,
         MAX(CASE WHEN account = 'Sales' THEN value_usd_m END) AS actual_sales,
         MAX(CASE WHEN account = 'SegmentOP' THEN value_usd_m END) AS actual_op
  FROM gold_cube WHERE scenario = 'Actual' AND entity = ticker GROUP BY ticker, fiscal_year
), charges AS (
  SELECT ticker, fiscal_year, SUM(amount_usd_m) AS charges FROM silver_charges GROUP BY ticker, fiscal_year
)
SELECT p.ticker, p.fiscal_year, p.plan_op, p.plan_sales, a.actual_sales,
       (a.actual_sales - p.plan_sales) * p.plan_op / p.plan_sales AS volume,
       -COALESCE(c.charges, 0) AS named_charges,
       a.actual_op - p.plan_op - (a.actual_sales - p.plan_sales) * p.plan_op / p.plan_sales
         + COALESCE(c.charges, 0) AS other,
       a.actual_op
FROM plan p
JOIN actual a ON a.ticker = p.ticker AND a.fiscal_year = p.fiscal_year
LEFT JOIN charges c ON c.ticker = p.ticker AND c.fiscal_year = p.fiscal_year
WHERE p.plan_op IS NOT NULL AND a.actual_op IS NOT NULL;

CREATE OR REFRESH MATERIALIZED VIEW gold_guidance_error AS
-- How far each guidance vintage landed from the actual: actual / midpoint - 1, and whether the
-- actual fell inside the guided range.
SELECT g.ticker, g.fiscal_year, g.scenario, g.release_date, g.account, g.low, g.high, g.mid,
       a.value_usd_m AS actual,
       a.value_usd_m / g.mid - 1 AS error_vs_mid,
       CASE WHEN a.value_usd_m BETWEEN g.low AND g.high THEN 1 ELSE 0 END AS inside_range
FROM silver_guidance g
JOIN gold_cube a ON a.ticker = g.ticker AND a.fiscal_year = g.fiscal_year AND a.entity = g.ticker
                AND a.account = g.account AND a.scenario = 'Actual';
